39	/// Static per-agent definition snapshot a Temporal worker plans and executes
40	/// against.
41	///
42	/// Built once per agent by
43	/// [`crate::worker::TemporalAgentWorkerBuilder::register`] and looked up by
44	/// name from the worker's process-local registry — **never serialized**.
45	/// `plan`'s `output` field (an `OutputType`) carries a `#[serde(skip)]`
46	/// validator that fails closed after any deserialize round-trip (SMA-332
47	/// Task 6), so `DurableAgentDef` must stay in-process for the lifetime of
48	/// the worker rather than crossing any wire boundary.
49	pub(crate) struct DurableAgentDef<Ctx> {
50	    /// Agent name — the registry key and the [`ModelTurnAccumulator`]
51	    /// attribution for reassembled turns.
52	    pub name: String,
53	    /// System-prompt renderer.
54	    pub instructions: Arc<dyn Instructions<Ctx>>,
55	    /// The model this agent calls each turn.
56	    pub model: Arc<dyn Model>,
57	    /// Tools available to this agent.
58	    pub tools: Vec<Arc<dyn Tool<Ctx>>>,
59	    /// Snapshot of tool/model/output configuration the durable driver plans
60	    /// against.
61	    ///
62	    /// Written by [`crate::worker::TemporalAgentWorkerBuilder::register`] and
63	    /// read by [`crate::worker::TemporalAgentWorkerBuilder::build`], which
64	    /// clones it (`def.plan.clone()`) into the `Ctx`-free `AgentPlan` map the
65	    /// durable workflow plans against via `DurableDriver::new`.
66	    pub plan: AgentPlan,
67	}
68	
69	/// Invoke `model`, draining its event stream into one aggregated
70	/// [`ModelTurnResult`].
71	///
72	/// SDK-free: unit-testable without a Temporal worker. A
73	/// [`paigasus_helikon_core::ModelError`] from either [`Model::invoke`]
74	/// itself or a stream-level event degrades to [`ErrorKindPayload::Model`]; a
75	/// successfully-drained stream that fails to reassemble (invalid
76	/// tool-call-argument JSON) degrades to [`ErrorKindPayload::Other`].
77	pub(crate) async fn call_model_inner(
78	    model: &dyn Model,
79	    agent_name: &str,
80	    request: ModelRequest,
81	    cancel: CancellationToken,
82	) -> Result<ModelTurnResult, ErrorKindPayload> {
83	    use futures_util::StreamExt;
84	
85	    let mut stream = model
86	        .invoke(request, cancel)
87	        .await
88	        .map_err(|e| ErrorKindPayload::Model {
89	            message: e.to_string(),
90	        })?;
91	
92	    let mut acc = ModelTurnAccumulator::new(agent_name);
93	    while let Some(event) = stream.next().await {
94	        match event {
95	            Ok(ev) => acc.observe(&ev),
96	            Err(e) => {
97	                return Err(ErrorKindPayload::Model {
98	                    message: e.to_string(),
99	                });
100	            }
101	        }
102	    }
103	
104	    acc.finish()
105	        .map(ModelTurnResult)
106	        .map_err(|message| ErrorKindPayload::Other { message })
107	}
108	
109	/// Execute one tool call through the shared authorize -> invoke -> redact
110	/// pipeline ([`execute_tool_call`]) and return its outcome.
111	///
112	/// SDK-free. An unknown tool name or a denied/failed call is folded into
113	/// `outcome.result`'s `Err` string per [`execute_tool_call`]'s contract —
114	/// this function never panics and never returns an `Err` of its own. The
115	/// `AgentEvent::PermissionDenied` event `execute_tool_call` may also produce
116	/// is intentionally dropped here: v0's durable event log
117	/// (`DurableRunOutcome::events`) does not carry per-tool permission events;
118	/// the denial reason is already folded into the outcome's `Err` string.
119	pub(crate) async fn invoke_tool_inner<Ctx: Send + Sync + 'static>(
120	    def: &DurableAgentDef<Ctx>,
121	    run_ctx: &RunContext<Ctx>,
122	    call: ToolCallRequest,
123	) -> ToolCallOutcome {
124	    let tool_ctx = run_ctx.to_tool_context();
125	    execute_tool_call(&def.tools, run_ctx, &tool_ctx, &call)
126	        .await
127	        .0
128	}
129	
130	/// Render this agent's system-prompt text for `run_ctx`.
131	///
132	/// SDK-free.
133	pub(crate) async fn render_instructions_inner<Ctx: Send + Sync + 'static>(
134	    def: &DurableAgentDef<Ctx>,
135	    run_ctx: &RunContext<Ctx>,
136	) -> String {
137	    def.instructions.render(run_ctx)
138	}
