140	// ---------------------------------------------------------------------------
141	// Temporal activity layer (Step 4): thin, Ctx-erased wrapper over the inner
142	// functions above.
143	// ---------------------------------------------------------------------------
144	
145	/// `Ctx`-erased seam behind the (necessarily non-generic) `#[activities]`
146	/// impl block on [`AgentActivities`]. See the module docs for why this
147	/// erasure is required.
148	#[async_trait]
149	trait DurableAgentRuntime: Send + Sync {
150	    /// See [`render_instructions_inner`].
151	    async fn render_instructions(
152	        &self,
153	        agent_name: &str,
154	        cancel: CancellationToken,
155	    ) -> Result<String, ActivityError>;
156	    /// See [`call_model_inner`].
157	    async fn call_model(
158	        &self,
159	        agent_name: &str,
160	        request: ModelRequest,
161	        cancel: CancellationToken,
162	    ) -> Result<ModelTurnResult, ActivityError>;
163	    /// See [`invoke_tool_inner`].
164	    async fn invoke_tool(
165	        &self,
166	        agent_name: &str,
167	        call: ToolCallRequest,
168	        cancel: CancellationToken,
169	    ) -> Result<ToolCallOutcome, ActivityError>;
170	}
171	
172	/// The `Ctx`-generic [`DurableAgentRuntime`] implementer: the process-local
173	/// registry of every agent this worker was built with, plus the per-run
174	/// `Ctx` factory.
175	struct TypedRuntime<Ctx> {
176	    registry: Arc<HashMap<String, Arc<DurableAgentDef<Ctx>>>>,
177	    ctx_factory: Arc<dyn Fn() -> Ctx + Send + Sync>,
178	}
179	
180	impl<Ctx: Send + Sync + 'static> TypedRuntime<Ctx> {
181	    /// Look up the named agent, or a non-retryable [`ActivityError`] if no
182	    /// such agent is registered on this worker (a configuration error, not
183	    /// a transient one — retrying can't fix it).
184	    fn resolve(&self, agent_name: &str) -> Result<Arc<DurableAgentDef<Ctx>>, ActivityError> {
185	        self.registry.get(agent_name).cloned().ok_or_else(|| {
186	            ActivityError::application(ApplicationFailure::non_retryable(format!(
187	                "no agent named '{agent_name}' is registered on this worker"
188	            )))
189	        })
190	    }
191	
192	    /// A fresh ephemeral [`RunContext`] (in-memory session, no hooks) for one
193	    /// activity invocation, wired to `cancel`.
194	    fn run_context(&self, cancel: CancellationToken) -> RunContext<Ctx> {
195	        RunContext::ephemeral((self.ctx_factory)()).with_cancel(cancel)
196	    }
197	}
198	
199	#[async_trait]
200	impl<Ctx: Send + Sync + 'static> DurableAgentRuntime for TypedRuntime<Ctx> {
201	    async fn render_instructions(
202	        &self,
203	        agent_name: &str,
204	        cancel: CancellationToken,
205	    ) -> Result<String, ActivityError> {
206	        let def = self.resolve(agent_name)?;
207	        let run_ctx = self.run_context(cancel);
208	        Ok(render_instructions_inner(&def, &run_ctx).await)
209	    }
210	
211	    async fn call_model(
212	        &self,
213	        agent_name: &str,
214	        request: ModelRequest,
215	        cancel: CancellationToken,
216	    ) -> Result<ModelTurnResult, ActivityError> {
217	        let def = self.resolve(agent_name)?;
218	        call_model_inner(def.model.as_ref(), &def.name, request, cancel)
219	            .await
220	            .map_err(error_kind_to_activity_error)
221	    }
222	
223	    async fn invoke_tool(
224	        &self,
225	        agent_name: &str,
226	        call: ToolCallRequest,
227	        cancel: CancellationToken,
228	    ) -> Result<ToolCallOutcome, ActivityError> {
229	        let def = self.resolve(agent_name)?;
230	        let run_ctx = self.run_context(cancel);
231	        Ok(invoke_tool_inner(&def, &run_ctx, call).await)
232	    }
233	}
234	
235	/// Fold a non-retryable [`ErrorKindPayload`] into an [`ActivityError`],
236	/// carrying `serde_json::to_string(&kind)` as the failure's message/details
237	/// per ADR-10 (no silent auto-retry inside the loop) — a model failure the
238	/// workflow's `DurableDriver` should observe as terminal, not something
239	/// Temporal's own activity-retry machinery should mask by retrying
240	/// transparently.
241	fn error_kind_to_activity_error(kind: ErrorKindPayload) -> ActivityError {
242	    let json = serde_json::to_string(&kind).unwrap_or_else(|e| {
243	        format!(r#"{{"Other":{{"message":"failed to serialize ErrorKindPayload: {e}"}}}}"#)
244	    });
245	    ActivityError::application(ApplicationFailure::non_retryable(json))
246	}
247	
248	/// Race `work` against the activity's own cancellation signal.
249	///
250	/// If the activity is cancelled first, propagate that into `cancel` (so the
251	/// in-flight [`Model`]/[`Tool`] call can wind down per its own cancellation
252	/// contract) and then await `work` to completion, so callers still get a
253	/// coherent result instead of a dropped future — and so this never leaks a
254	/// detached task waiting on a cancellation signal that may never fire.
255	async fn race_with_activity_cancellation<T>(
256	    activity_ctx: &ActivityContext,
257	    cancel: CancellationToken,
258	    work: impl std::future::Future<Output = T>,
259	) -> T {
260	    tokio::pin!(work);
261	    tokio::select! {
262	        biased;
263	        result = &mut work => result,
264	        _ = activity_ctx.cancelled() => {
265	            cancel.cancel();
266	            work.await
267	        }
268	    }
269	}
270	
271	/// The `Ctx`-erased, non-generic activities struct registered on the
272	/// worker's task queue. See the module docs for why it holds a trait object
273	/// rather than a `Ctx`-generic field directly.
274	pub(crate) struct AgentActivities {
275	    runtime: Arc<dyn DurableAgentRuntime>,
276	}
277	
278	/// Build the [`AgentActivities`] instance a [`crate::worker::TemporalAgentWorker`]
279	/// registers for its task queue, from a `Ctx`-generic registry + ctx
280	/// factory. This is the erasure boundary: past this call, `Ctx` no longer
281	/// appears in any type the Temporal SDK holds onto.
282	pub(crate) fn build_activities<Ctx: Send + Sync + 'static>(
283	    registry: Arc<HashMap<String, Arc<DurableAgentDef<Ctx>>>>,
284	    ctx_factory: Arc<dyn Fn() -> Ctx + Send + Sync>,
285	) -> AgentActivities {
286	    AgentActivities {
287	        runtime: Arc::new(TypedRuntime {
288	            registry,
289	            ctx_factory,
290	        }),
291	    }
292	}
