294	#[temporalio_macros::activities]
295	impl AgentActivities {
296	    /// Render the named agent's system-prompt text.
297	    ///
298	    /// Render the named agent's system-prompt text.
299	    ///
300	    /// `pub(crate)` so `#[activities]` emits a `pub(crate)` associated const
301	    /// (`AgentActivities::render_instructions`) — the typed activity marker
302	    /// SMA-332 Task 8's workflow passes to `WorkflowContext::start_activity`
303	    /// from the sibling `workflow` module.
304	    #[activity]
305	    pub(crate) async fn render_instructions(
306	        self: Arc<Self>,
307	        ctx: ActivityContext,
308	        agent_name: String,
309	    ) -> Result<String, ActivityError> {
310	        let cancel = CancellationToken::new();
311	        race_with_activity_cancellation(
312	            &ctx,
313	            cancel.clone(),
314	            self.runtime.render_instructions(&agent_name, cancel),
315	        )
316	        .await
317	    }
318	
319	    /// Invoke the named agent's model for one turn.
320	    ///
321	    /// `pub(crate)` for the same marker-visibility reason as
322	    /// [`AgentActivities::render_instructions`].
323	    #[activity]
324	    pub(crate) async fn call_model(
325	        self: Arc<Self>,
326	        ctx: ActivityContext,
327	        agent_name: String,
328	        request: ModelRequest,
329	    ) -> Result<ModelTurnResult, ActivityError> {
330	        let cancel = CancellationToken::new();
331	        race_with_activity_cancellation(
332	            &ctx,
333	            cancel.clone(),
334	            self.runtime.call_model(&agent_name, request, cancel),
335	        )
336	        .await
337	    }
338	
339	    /// Execute one tool call for the named agent.
340	    ///
341	    /// `pub(crate)` for the same marker-visibility reason as
342	    /// [`AgentActivities::render_instructions`].
343	    #[activity]
344	    pub(crate) async fn invoke_tool(
345	        self: Arc<Self>,
346	        ctx: ActivityContext,
347	        agent_name: String,
348	        call: ToolCallRequest,
349	    ) -> Result<ToolCallOutcome, ActivityError> {
350	        let cancel = CancellationToken::new();
351	        race_with_activity_cancellation(
352	            &ctx,
353	            cancel.clone(),
354	            self.runtime.invoke_tool(&agent_name, call, cancel),
355	        )
356	        .await
357	    }
358	}
