390	    // ---- error_kind_to_activity_error (ADR-10) ------------------------
391	
392	    /// ADR-10: a model failure must be a **non-retryable** application error
393	    /// so Temporal's activity-retry machinery does not silently mask it — the
394	    /// workflow's `DurableDriver` must observe it as terminal. This is the
395	    /// embodiment of "the runner never retries model errors".
396	    #[test]
397	    fn error_kind_to_activity_error_model_is_non_retryable() {
398	        let err = error_kind_to_activity_error(ErrorKindPayload::Model {
399	            message: "connection lost".to_owned(),
400	        });
401	        match err {
402	            ActivityError::Application(app) => {
403	                assert!(
404	                    app.is_non_retryable(),
405	                    "ADR-10: model-failure activity errors must be non-retryable"
406	                );
407	            }
408	            other => panic!("expected ActivityError::Application, got {other:?}"),
409	        }
410	    }
