459	    #[tokio::test]
460	    async fn call_model_inner_aggregates_happy_path() {
461	        let model = ScriptedModel::new(vec![
462	            Ok(ModelEvent::TokenDelta { text: "hel".into() }),
463	            Ok(ModelEvent::TokenDelta { text: "lo".into() }),
464	            Ok(ModelEvent::Usage {
465	                input_tokens: 3,
466	                output_tokens: 2,
467	                cached_input_tokens: None,
468	                reasoning_tokens: None,
469	            }),
470	            Ok(ModelEvent::Finish {
471	                reason: FinishReason::Stop,
472	            }),
473	        ]);
474	
475	        let result = call_model_inner(
476	            &model,
477	            "agent-1",
478	            ModelRequest::new(),
479	            CancellationToken::new(),
480	        )
481	        .await
482	        .expect("happy path succeeds");
483	
484	        assert_eq!(result.0.items.len(), 1);
485	        match &result.0.items[0] {
486	            Item::AssistantMessage { content, agent } => {
487	                assert_eq!(agent.as_deref(), Some("agent-1"));
488	                match &content[0] {
489	                    ContentPart::Text { text } => assert_eq!(text, "hello"),
490	                    other => panic!("expected Text, got {other:?}"),
491	                }
492	            }
493	            other => panic!("expected AssistantMessage, got {other:?}"),
494	        }
495	        assert_eq!(result.0.usage.input_tokens, 3);
496	        assert_eq!(result.0.usage.output_tokens, 2);
497	        assert_eq!(result.0.finish_reason, FinishReason::Stop);
498	    }
