421	fn protected_path_write(tool: &str, args: &serde_json::Value) -> bool {
422	    if matches!(tool, "Write" | "Edit") {
423	        if let Some(p) = args.get("path").and_then(|v| v.as_str()) {
424	            return is_protected_path(p);
425	        }
426	    }
427	    if let Some(cmd) = bash_command_str(tool, args) {
428	        for c in crate::command_match::resolve_all(cmd) {
429	            for r in &c.redirects {
430	                use crate::command_match::RedirectOp;
431	                if matches!(r.op, RedirectOp::Out | RedirectOp::Append)
432	                    && is_protected_path(&r.target)
433	                {
434	                    return true;
435	                }
436	            }
437	            if c.program == "tee" && c.args.iter().any(|a| is_protected_path(a)) {
438	                return true;
439	            }
440	            if c.program == "dd" {
441	                if let Some(of) = c.args.iter().find_map(|a| a.strip_prefix("of=")) {
442	                    if is_protected_path(of) {
443	                        return true;
444	                    }
445	                }
446	            }
447	        }
448	    }
449	    false
450	}
