465	                    && crate::path_match::is_protected_dotpath(&r.target)
466	                {
467	                    return true;
468	                }
469	            }
470	            if c.program == "tee"
471	                && c.args
472	                    .iter()
473	                    .any(|a| crate::path_match::is_protected_dotpath(a))
474	            {
475	                return true;
476	            }
477	            if c.program == "dd" {
