489	fn is_protected_path(path: &str) -> bool {
490	    if DEVICE_ALLOWLIST.contains(&path) {
491	        return false;
492	    }
493	    if path == "/" {
494	        return true;
495	    }
496	    PROTECTED_PREFIXES
497	        .iter()
498	        .any(|p| path == *p || path.starts_with(&format!("{p}/")))
499	}
