75	/// A durable, Temporal-backed [`Runner`].
76	///
77	/// Holds a connected [`temporalio_client::Client`] and a
78	/// [`TemporalRunnerConfig`]; each `run` starts one durable workflow execution
79	/// on the configured task queue. Construct via [`TemporalRunner::new`].
80	pub struct TemporalRunner {
81	    client: Client,
82	    config: TemporalRunnerConfig,
83	}
84	
85	impl TemporalRunner {
86	    /// Build a runner from a connected client and its configuration.
87	    pub fn new(client: Client, config: TemporalRunnerConfig) -> Self {
88	        Self { client, config }
89	    }
90	
91	    /// Run the durable workflow to completion, racing the client's cancel
92	    /// token against the awaited result: a fired token requests cooperative
93	    /// workflow cancellation, after which the workflow still returns a total
94	    /// (`Cancelled`) outcome.
95	    async fn run_workflow(
96	        &self,
97	        input: WorkflowInput,
98	        timeout: Option<Duration>,
99	        cancel: CancellationToken,
100	    ) -> Result<DurableRunOutcome, RunError> {
101	        // Workflow id is minted client-side (never inside the workflow, which
102	        // must stay deterministic).
103	        let workflow_id = self
104	            .config
105	            .workflow_id
106	            .clone()
107	            .unwrap_or_else(|| format!("helikon-run-{}", uuid::Uuid::new_v4()));
108	
109	        let execution_timeout =
110	            timeout.map(|d| d.saturating_add(self.config.execution_timeout_margin));
111	        let start_opts = WorkflowStartOptions::new(self.config.task_queue.clone(), workflow_id)
112	            .maybe_execution_timeout(execution_timeout)
113	            .build();
114	
115	        let handle = self
116	            .client
117	            .start_workflow(
118	                crate::workflow::DurableAgentWorkflow::run,
119	                input,
120	                start_opts,
121	            )
122	            .await
123	            .map_err(|e| {
124	                RunError::Other(anyhow::anyhow!("failed to start temporal workflow: {e}"))
125	            })?;
126	
127	        let get_result = handle.get_result(WorkflowGetResultOptions::default());
128	        tokio::pin!(get_result);
129	        let mut requested_cancel = false;
130	        let outcome = loop {
131	            tokio::select! {
132	                result = &mut get_result => break result,
133	                // Once the run's cancel token fires, request cooperative
134	                // workflow cancellation once, then keep awaiting the (now
135	                // `Cancelled`) total outcome.
136	                () = cancel.cancelled(), if !requested_cancel => {
137	                    requested_cancel = true;
138	                    let _ = handle.cancel(WorkflowCancelOptions::default()).await;
139	                }
140	            }
141	        };
142	
143	        outcome.map_err(|e| RunError::Other(anyhow::anyhow!("temporal workflow failed: {e}")))
144	    }
145	
146	    /// Shared run path for both [`Runner::run`] and [`Runner::run_streamed`].
147	    ///
148	    /// Returns the run's events plus its mapped terminal result. The outer
149	    /// `Err` is reserved for a session **read** failure (load fails before the
150	    /// run starts); every other exit — including workflow start/await
151	    /// infrastructure failures — finalizes the session recorder and reports its
152	    /// outcome as the inner `Result`.
153	    async fn run_inner<Ctx>(
154	        &self,
155	        agent: &(dyn Agent<Ctx> + '_),
156	        ctx: RunContext<Ctx>,
157	        input: AgentInput,
158	        config: RunConfig,
159	    ) -> Result<(Vec<AgentEvent>, Result<RunResult, RunError>), RunError>
160	    where
161	        Ctx: Send + Sync + 'static,
162	    {
163	        let timeout = config.timeout;
164	        let max_turns = config.max_turns;
165	        let parallel_tool_call_limit = config.parallel_tool_call_limit;
166	
167	        let ctx = ctx.with_run_config(config);
168	        let cancel = ctx.cancel().clone();
169	        let session = ctx.session().clone();
170	
171	        // Session read failure is a hard error (mirrors `TokioRunner`).
172	        let (merged, recorder) = load_and_record(&session, agent.name(), input).await?;
173	
174	        let workflow_input = WorkflowInput {
175	            agent_name: agent.name().to_owned(),
176	            conversation: merged.messages,
177	            config: DriverConfig {
178	                max_turns,
179	                parallel_tool_call_limit: parallel_tool_call_limit.map(|n| n.get()),
180	            },
181	            timeout_ms: timeout.map(|d| d.as_millis() as u64),
182	        };
183	
184	        match self.run_workflow(workflow_input, timeout, cancel).await {
185	            Ok(outcome) => {
186	                {
187	                    let mut rec = recorder.lock().expect("session recorder mutex poisoned");
188	                    for event in &outcome.events {
189	                        rec.observe(event);
190	                    }
191	                }
192	                finalize(&session, &recorder).await;
193	                let events = outcome.events.clone();
194	                Ok((events, outcome_to_run_result(outcome)))
195	            }
196	            Err(infra) => {
197	                // Infra failure: still finalize (the recorder holds this turn's
198	                // new-turn input) before surfacing the error.
199	                finalize(&session, &recorder).await;
200	                Ok((Vec::new(), Err(infra)))
201	            }
202	        }
203	    }
204	}
205	
206	#[async_trait]
207	impl<Ctx> Runner<Ctx> for TemporalRunner
208	where
209	    Ctx: Send + Sync + 'static,
210	{
211	    async fn run(
212	        &self,
213	        agent: &(dyn Agent<Ctx> + '_),
214	        ctx: RunContext<Ctx>,
215	        input: AgentInput,
216	        config: RunConfig,
217	    ) -> Result<RunResult, RunError> {
218	        let (_events, result) = self.run_inner(agent, ctx, input, config).await?;
219	        result
220	    }
221	
222	    /// **Buffered, not live.** The durable workflow runs to completion first;
223	    /// the returned stream then replays the already-recorded
224	    /// [`AgentEvent`]s as an immediate, finite stream. Because persistence
225	    /// happened *before* the stream exists (a strictly stronger guarantee than
226	    /// the trait's warning), dropping the stream early loses nothing. Live
227	    /// token streaming across the workflow boundary is future work.
228	    ///
229	    /// On a failed run the terminal error is wired into the returned handle's
230	    /// [`FailureSlot`] and a terminal `RunFailed` event is guaranteed present,
231	    /// so [`RunResultStreaming::collect`] surfaces the typed
232	    /// [`RunError::Agent`] — matching `TokioRunner`.
233	    async fn run_streamed(
234	        &self,
235	        agent: &(dyn Agent<Ctx> + '_),
236	        ctx: RunContext<Ctx>,
237	        input: AgentInput,
238	        config: RunConfig,
239	    ) -> Result<RunResultStreaming, RunError> {
240	        let (mut events, result) = self.run_inner(agent, ctx, input, config).await?;
241	
242	        let failure = FailureSlot::new();
243	        let terminal_message = match result {
244	            Ok(_) => None,
245	            Err(RunError::Agent(err)) => {
246	                let message = err.to_string();
247	                failure.set(err);
248	                Some(message)
249	            }
250	            Err(other) => Some(other.to_string()),
251	        };
252	
253	        // `collect()` only reads the failure slot once it observes a terminal
254	        // `RunFailed` in the stream. The durable event log already carries one
255	        // for `AgentFailed` runs; synthesize one for the terminal states that
256	        // do not (cancellation/timeout/infra), so a failed run never collects
257	        // as `Ok`.
258	        if let Some(message) = terminal_message {
259	            if !matches!(events.last(), Some(AgentEvent::RunFailed { .. })) {
260	                events.push(AgentEvent::RunFailed { error: message });
261	            }
262	        }
263	
264	        Ok(RunResultStreaming::with_failure(
265	            stream::iter(events).boxed(),
266	            failure,
267	        ))
268	    }
269	}
270	
271	/// Snapshot the session into the merged input and seed a recorder with the
272	/// run's new-turn messages. A read failure is a hard error: the run cannot
273	/// faithfully resume from an unreadable session. (Mirrors
274	/// `TokioRunner::load_and_record`.)
275	async fn load_and_record(
276	    session: &Arc<dyn Session>,
277	    agent_name: &str,
278	    input: AgentInput,
279	) -> Result<(AgentInput, Arc<Mutex<SessionRecorder>>), RunError> {
280	    let snapshot = session
281	        .snapshot()
282	        .await
283	        .map_err(|e| RunError::Other(anyhow::Error::new(e)))?;
284	    let mut recorder = SessionRecorder::new(agent_name);
285	    recorder.record_input(&input.messages);
286	
287	    let mut merged = AgentInput::new();
288	    merged.messages = snapshot.messages;
289	    merged.messages.extend(input.messages);
290	    Ok((merged, Arc::new(Mutex::new(recorder))))
291	}
292	
293	/// Post-run finalization: drain the recorder and append the run's events.
294	/// Persistence is best-effort — an append error is logged, never propagated.
295	/// (Mirrors `TokioRunner::finalize`.)
296	async fn finalize(session: &Arc<dyn Session>, recorder: &Arc<Mutex<SessionRecorder>>) {
297	    let events = recorder
298	        .lock()
299	        .expect("session recorder mutex poisoned")
300	        .drain();
301	    if let Err(e) = session.append(&events).await {
302	        tracing::warn!(
303	            error = %e,
304	            "session persistence failed during finalize; run outcome unaffected"
305	        );
306	    }
307	}
