55	/// Default per-attempt activity timeout (start-to-close) for every durable
56	/// activity this workflow schedules.
57	///
58	/// v0 uses one generous default so a slow model or tool call does not fail its
59	/// attempt spuriously; a crashed worker's in-flight attempt still times out
60	/// after this bound and is re-dispatched per the activity's retry policy.
61	/// Override per activity via [`crate::worker::TemporalAgentWorkerBuilder::model_start_to_close`]
62	/// / [`crate::worker::TemporalAgentWorkerBuilder::tool_start_to_close`].
63	const DEFAULT_ACTIVITY_START_TO_CLOSE: Duration = Duration::from_secs(300);
64	
65	/// Per-activity start-to-close timeout overrides.
66	///
67	/// Each field bounds a **single execution attempt** of the corresponding
68	/// activity (`render_instructions` / `call_model` / `invoke_tool`). Temporal
69	/// detects a dead worker only by an activity attempt overrunning its
70	/// start-to-close bound, so a shorter `tool`/`model` timeout is what makes a
71	/// crashed worker's in-flight attempt re-dispatch promptly — the knob a
72	/// crash-resume-sensitive deployment (or the crash-resume test) tunes down.
73	/// Defaults to [`DEFAULT_ACTIVITY_START_TO_CLOSE`] for all three.
74	#[derive(Debug, Clone, Copy)]
75	pub(crate) struct ActivityTimeouts {
76	    /// Start-to-close for the `render_instructions` activity.
77	    pub instructions: Duration,
78	    /// Start-to-close for the `call_model` activity.
79	    pub model: Duration,
80	    /// Start-to-close for the `invoke_tool` activity.
81	    pub tool: Duration,
82	}
83	
84	impl Default for ActivityTimeouts {
85	    fn default() -> Self {
86	        Self {
87	            instructions: DEFAULT_ACTIVITY_START_TO_CLOSE,
88	            model: DEFAULT_ACTIVITY_START_TO_CLOSE,
89	            tool: DEFAULT_ACTIVITY_START_TO_CLOSE,
90	        }
91	    }
92	}
93	
94	/// Process-local, `Ctx`-free durable-run configuration the workflow factory
95	/// closes over.
96	///
97	/// Built once per worker by [`build_activity_config`] and cloned (via `Arc`)
98	/// into every [`DurableAgentWorkflow`] instance the factory produces. Never
99	/// serialized — an [`AgentPlan`]'s `OutputType` validator does not survive a
100	/// deserialize round-trip.
101	pub(crate) struct WorkflowActivityConfig {
102	    /// Agent plans keyed by name, resolved by [`WorkflowInput::agent_name`]
103	    /// with a single [`HashMap::get`] (never iterated inside the workflow).
104	    plans: HashMap<String, AgentPlan>,
105	    /// [`ActivityOptions`] for the `render_instructions` activity (no
106	    /// caller-configurable retry policy in v0 — uses the Temporal server
107	    /// default).
108	    instructions_activity_opts: ActivityOptions,
109	    /// [`ActivityOptions`] for the `call_model` activity, carrying the
110	    /// worker's configured model retry policy.
111	    model_activity_opts: ActivityOptions,
112	    /// [`ActivityOptions`] for the `invoke_tool` activity, carrying the
113	    /// worker's configured tool retry policy.
114	    tool_activity_opts: ActivityOptions,
115	}
116	
117	/// Assemble the [`WorkflowActivityConfig`] the worker's
118	/// `register_workflow_with_factory` closure clones into each workflow
119	/// instance.
120	///
121	/// `plans` is the `Ctx`-free projection of the worker's agent registry
122	/// (`name → AgentPlan`); `model_retry`/`tool_retry` are the builder's
123	/// [`RetryPolicyConfig`]s, converted here into the proto retry policy attached
124	/// to the corresponding activity options (un-inerting the fields Task 7
125	/// stored); `timeouts` supplies the per-activity start-to-close bound.
126	pub(crate) fn build_activity_config(
127	    plans: HashMap<String, AgentPlan>,
128	    model_retry: &RetryPolicyConfig,
129	    tool_retry: &RetryPolicyConfig,
130	    timeouts: &ActivityTimeouts,
131	) -> WorkflowActivityConfig {
132	    WorkflowActivityConfig {
133	        plans,
134	        instructions_activity_opts: activity_opts(timeouts.instructions, None),
135	        model_activity_opts: activity_opts(timeouts.model, to_proto_retry_policy(model_retry)),
136	        tool_activity_opts: activity_opts(timeouts.tool, to_proto_retry_policy(tool_retry)),
137	    }
138	}
139	
140	/// Build [`ActivityOptions`] with the given start-to-close timeout and an
141	/// optional retry policy.
142	fn activity_opts(start_to_close: Duration, retry_policy: Option<RetryPolicy>) -> ActivityOptions {
143	    ActivityOptions::with_start_to_close_timeout(start_to_close)
144	        .maybe_retry_policy(retry_policy)
145	        .build()
146	}
147	
148	/// Convert a [`RetryPolicyConfig`] into the proto retry policy Temporal's
149	/// [`ActivityOptions`] expects.
150	///
151	/// Returns `None` when every field is unset/empty, so the activity uses the
152	/// Temporal server's own default retry policy rather than an all-zero proto.
153	fn to_proto_retry_policy(cfg: &RetryPolicyConfig) -> Option<RetryPolicy> {
154	    let is_default = cfg.initial_interval.is_none()
155	        && cfg.backoff_coefficient.is_none()
156	        && cfg.maximum_interval.is_none()
157	        && cfg.maximum_attempts.is_none()
158	        && cfg.non_retryable_error_types.is_empty();
159	    if is_default {
160	        return None;
161	    }
162	
163	    // A prost-generated message. `backoff_coefficient = 0.0` and
164	    // `maximum_attempts = 0` are the proto's "server default" sentinels, so
165	    // leaving an unset field at its `Default` here is correct (unlimited
166	    // attempts / server-default backoff).
167	    Some(RetryPolicy {
168	        initial_interval: cfg.initial_interval.and_then(|d| d.try_into().ok()),
169	        backoff_coefficient: cfg.backoff_coefficient.unwrap_or_default(),
170	        maximum_interval: cfg.maximum_interval.and_then(|d| d.try_into().ok()),
171	        maximum_attempts: cfg
172	            .maximum_attempts
173	            .map(|max| i32::try_from(max).unwrap_or(i32::MAX))
174	            .unwrap_or_default(),
175	        non_retryable_error_types: cfg.non_retryable_error_types.clone(),
176	    })
177	}
178	
179	/// The durable agent-loop workflow.
180	///
181	/// Registered on the worker's task queue via
182	/// [`crate::worker::TemporalAgentWorkerBuilder::build`]'s
183	/// `register_workflow_with_factory` call. Started per run by
184	/// [`crate::runner::TemporalRunner`], which passes the [`Self::run`] marker to
185	/// `temporalio_client::Client::start_workflow`.
186	#[workflow]
187	pub(crate) struct DurableAgentWorkflow {
188	    /// Process-local run configuration (agent plans + activity options),
189	    /// cloned in by the workflow factory.
190	    config: Arc<WorkflowActivityConfig>,
191	}
192	
193	impl DurableAgentWorkflow {
194	    /// Construct a workflow instance for the factory closure. Cheap: clones a
195	    /// single `Arc`.
196	    pub(crate) fn new(config: Arc<WorkflowActivityConfig>) -> Self {
197	        Self { config }
198	    }
199	}
200	
201	#[workflow_methods(factory_only)]
202	impl DurableAgentWorkflow {
203	    /// Drive one durable agent run to a total [`DurableRunOutcome`].
204	    ///
205	    /// `factory_only`: the instance (and its `config`) is produced by the
206	    /// worker's factory closure, so no `#[init]`/`Default` is needed; `run`
207	    /// reads the closed-over config from workflow state via
208	    /// [`WorkflowContext::state`].
209	    #[run]
210	    pub(crate) async fn run(
211	        ctx: &mut WorkflowContext<Self>,
212	        input: WorkflowInput,
213	    ) -> WorkflowResult<DurableRunOutcome> {
214	        let config = ctx.state(|w| Arc::clone(&w.config));
215	        Ok(drive(&*ctx, config, input).await)
216	    }
217	}
218	
219	/// Run the driver loop, racing it against the run-deadline timer and workflow
220	/// cancellation. Always returns a total outcome.
221	async fn drive(
222	    ctx: &WorkflowContext<DurableAgentWorkflow>,
223	    config: Arc<WorkflowActivityConfig>,
224	    input: WorkflowInput,
225	) -> DurableRunOutcome {
226	    let agent_name = input.agent_name.clone();
227	    let timeout_ms = input.timeout_ms;
228	    let parallel_limit = input.config.parallel_tool_call_limit;
229	
230	    // Single keyed lookup — deterministic, not a `HashMap` iteration.
231	    let plan = match config.plans.get(&agent_name) {
232	        Some(plan) => plan.clone(),
233	        None => return unknown_agent_outcome(&agent_name),
234	    };
235	
236	    let mut driver = DurableDriver::new(input, plan);
237	
238	    // Race the whole effect loop against (a) the durable run-deadline timer
239	    // and (b) cooperative cancellation. The `select!` block owns the borrow of
240	    // `driver` (via `effects`); it is released at the block's end, before
241	    // `driver.interrupt(..)` consumes the driver on an interruption. A natural
242	    // finish `return`s the outcome directly from inside the loop.
243	    let interrupt = {
244	        let effects = run_effects(ctx, &config, &agent_name, parallel_limit, &mut driver).fuse();
245	        let deadline = run_deadline(ctx, timeout_ms).fuse();
246	        let cancelled = ctx.cancelled();
247	        futures_util::pin_mut!(effects, deadline, cancelled);
248	
249	        temporalio_sdk::workflows::select! {
250	            outcome = effects => return outcome,
251	            _ = deadline => InterruptKind::TimedOut,
252	            _ = cancelled => InterruptKind::Cancelled,
253	        }
254	    };
255	
256	    driver.interrupt(interrupt)
257	}
258	
259	/// The run-deadline future: a durable timer of `timeout_ms`, or a never-
260	/// resolving future when no deadline is configured.
261	async fn run_deadline(ctx: &WorkflowContext<DurableAgentWorkflow>, timeout_ms: Option<u64>) {
262	    match timeout_ms {
263	        Some(ms) => {
264	            let _ = ctx.timer(Duration::from_millis(ms)).await;
265	        }
266	        None => futures_util::future::pending::<()>().await,
267	    }
268	}
269	
270	/// Execute driver effects one activity at a time until the driver reports a
271	/// terminal outcome.
272	async fn run_effects(
273	    ctx: &WorkflowContext<DurableAgentWorkflow>,
274	    config: &WorkflowActivityConfig,
275	    agent_name: &str,
276	    parallel_limit: Option<usize>,
277	    driver: &mut DurableDriver,
278	) -> DurableRunOutcome {
279	    loop {
280	        match driver.next_effect() {
281	            DriverEffect::RenderInstructions => {
282	                match ctx
283	                    .start_activity(
284	                        AgentActivities::render_instructions,
285	                        agent_name.to_owned(),
286	                        config.instructions_activity_opts.clone(),
287	                    )
288	                    .await
289	                {
290	                    Ok(system_text) => driver.apply_instructions(system_text),
291	                    // An infra-level failure of the (otherwise deterministic)
292	                    // render step is terminal — surface it like a model
293	                    // failure so the run finalizes with events-so-far.
294	                    Err(err) => driver.apply_model_failure(extract_error_kind(&err)),
295	                }
296	            }
297	            DriverEffect::CallModel(request) => {
298	                match ctx
299	                    .start_activity(
300	                        AgentActivities::call_model,
301	                        (agent_name.to_owned(), request),
302	                        config.model_activity_opts.clone(),
303	                    )
304	                    .await
305	                {
306	                    Ok(turn) => driver.apply_model(turn),
307	                    // ADR-10: `call_model` marks model errors non-retryable and
308	                    // carries an `ErrorKindPayload` JSON in the failure — parse
309	                    // it back and feed the terminal failure to the driver.
310	                    Err(err) => driver.apply_model_failure(extract_error_kind(&err)),
311	                }
312	            }
313	            DriverEffect::ExecuteTools(calls) => {
314	                let outcomes = execute_tools(ctx, config, agent_name, parallel_limit, calls).await;
315	                driver.apply_tools(outcomes);
316	            }
317	            DriverEffect::Finished(outcome) => return outcome,
318	        }
319	    }
320	}
321	
322	/// Execute one turn's tool calls, started concurrently and chunked by
323	/// `parallel_limit`, returning the outcomes **in original call order** (the
324	/// driver reassembles tool results by position, not by completion order).
325	async fn execute_tools(
326	    ctx: &WorkflowContext<DurableAgentWorkflow>,
327	    config: &WorkflowActivityConfig,
328	    agent_name: &str,
329	    parallel_limit: Option<usize>,
330	    calls: Vec<ToolCallRequest>,
331	) -> Vec<ToolCallOutcome> {
332	    // `None`/`0` ⇒ no concurrency cap: one chunk of every call.
333	    let chunk_size = parallel_limit
334	        .filter(|&n| n > 0)
335	        .unwrap_or_else(|| calls.len().max(1));
336	
337	    let mut outcomes = Vec::with_capacity(calls.len());
338	    for chunk in calls.chunks(chunk_size) {
339	        let started = chunk.iter().map(|call| {
340	            let call = call.clone();
341	            let call_id = call.call_id.clone();
342	            let opts = config.tool_activity_opts.clone();
343	            let agent_name = agent_name.to_owned();
344	            async move {
345	                match ctx
346	                    .start_activity(AgentActivities::invoke_tool, (agent_name, call), opts)
347	                    .await
348	                {
349	                    Ok(outcome) => outcome,
350	                    // Tool-level errors are already `Ok(ToolCallOutcome{ result:
351	                    // Err(..) })`. Reaching an `Err` here means the activity
352	                    // itself failed at the infra level (e.g. exhausted retries,
353	                    // unregistered agent). Fold it into a tool-error outcome so
354	                    // the loop stays total and the model sees a tool failure —
355	                    // Task 9 validates the live crash-resume path.
356	                    Err(err) => ToolCallOutcome {
357	                        call_id,
358	                        result: Err(format!(
359	                            "tool activity failed: {}",
360	                            activity_failure_message(&err)
361	                        )),
362	                    },
363	                }
364	            }
365	        });
366	        // `join_all` preserves input order in its result `Vec` (deterministic).
367	        let chunk_outcomes = temporalio_sdk::workflows::join_all(started).await;
368	        outcomes.extend(chunk_outcomes);
369	    }
370	    outcomes
371	}
372	
373	/// Reconstruct the [`ErrorKindPayload`] a `call_model` activity failure carries
374	/// (the non-retryable [`ErrorKindPayload`] JSON from
375	/// [`crate::activities`]'s `error_kind_to_activity_error`), degrading to
376	/// [`ErrorKindPayload::Model`] with the raw failure message when the payload
377	/// cannot be parsed (e.g. an infra failure that never went through that path).
378	fn extract_error_kind(err: &ActivityExecutionError) -> ErrorKindPayload {
379	    let message = activity_failure_message(err);
380	    serde_json::from_str::<ErrorKindPayload>(&message)
381	        .unwrap_or(ErrorKindPayload::Model { message })
382	}
383	
384	/// Best-effort extraction of the human-readable message from an activity
385	/// failure: prefer the application-failure cause's message (which carries the
386	/// `ErrorKindPayload` JSON), then the top-level failure message, then the
387	/// error's `Display`.
388	fn activity_failure_message(err: &ActivityExecutionError) -> String {
389	    if let Some(cause) = err.cause() {
390	        return cause.failure().message.clone();
391	    }
392	    if let Some(failure) = err.failure() {
393	        return failure.message.clone();
394	    }
395	    err.to_string()
396	}
397	
398	/// Terminal outcome for a run whose agent name is not registered on this
399	/// worker. Deterministic (no activity, no time) — the client cannot
400	/// pre-validate the worker's registry, so this surfaces at run start.
401	fn unknown_agent_outcome(agent_name: &str) -> DurableRunOutcome {
402	    DurableRunOutcome {
403	        status: RunStatusPayload::AgentFailed(ErrorKindPayload::Other {
404	            message: format!("no agent named '{agent_name}' is registered on this worker"),
405	        }),
406	        events: Vec::new(),
407	        usage: TokenUsage::default(),
408	    }
409	}
